with SupplierSummary as (select supplier_id, count(distinct stock_qty) as unique_suppliers, sort_array(collect_set(category)) as category_list from products where month(launch_date) in (6, 7, 11) group by supplier_id) select s.rating, s.supplier_name, S.unique_suppliers, S.category_list from suppliers s inner join SupplierSummary S on s.id = S.supplier_id where S.unique_suppliers >= 7
